-- Remaining MariaDB domain tables. No seed data is inserted.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS workplaces (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,code VARCHAR(64) NOT NULL UNIQUE,address TEXT NOT NULL,phone VARCHAR(128) NOT NULL,email VARCHAR(255) NOT NULL,currency VARCHAR(16) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'active',deleted_at DATETIME(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS brands (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,description TEXT NOT NULL DEFAULT '',status VARCHAR(16) NOT NULL DEFAULT 'active',deleted_at DATETIME(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS series (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,brand_id INT UNSIGNED NULL,name VARCHAR(255) NOT NULL,description TEXT NOT NULL DEFAULT '',status VARCHAR(16) NOT NULL DEFAULT 'active',deleted_at DATETIME(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),KEY(brand_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS warehouses (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workplace_id INT UNSIGNED NULL,name VARCHAR(255) NOT NULL,address TEXT NOT NULL,manager_name VARCHAR(255) NOT NULL DEFAULT '',status VARCHAR(16) NOT NULL DEFAULT 'active',deleted_at DATETIME(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS services (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workplace_id INT UNSIGNED NULL,name VARCHAR(255) NOT NULL,description TEXT NOT NULL,price DECIMAL(16,2) NOT NULL DEFAULT 0,currency VARCHAR(16) NOT NULL DEFAULT 'IQD',status VARCHAR(16) NOT NULL DEFAULT 'active',deleted_at DATETIME(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS user_groups (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workplace_id INT UNSIGNED NULL,name VARCHAR(255) NOT NULL,permissions JSON NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'active',deleted_at DATETIME(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workplace_id INT UNSIGNED NULL,group_id INT UNSIGNED NULL,username VARCHAR(255) NOT NULL UNIQUE,display_name VARCHAR(255) NOT NULL,password_hash VARCHAR(255) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'active',last_login_at DATETIME(3),deleted_at DATETIME(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS employees (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workplace_id INT UNSIGNED NULL,user_id INT UNSIGNED NULL,name VARCHAR(255) NOT NULL,phone VARCHAR(128) NOT NULL,email VARCHAR(255) NOT NULL,address TEXT NOT NULL,job_title VARCHAR(255) NOT NULL,department VARCHAR(255) NOT NULL,start_date DATE,end_date DATE,compensation DECIMAL(16,2),compensation_currency VARCHAR(16),status VARCHAR(16) NOT NULL DEFAULT 'active',deleted_at DATETIME(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS drivers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workplace_id INT UNSIGNED NULL,name VARCHAR(255) NOT NULL,phone VARCHAR(128) NOT NULL,address TEXT NOT NULL,vehicle_info VARCHAR(255) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'active',deleted_at DATETIME(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS account_categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,account_type VARCHAR(32) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'active',deleted_at DATETIME(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cash_boxes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workplace_id INT UNSIGNED NOT NULL,name VARCHAR(255) NOT NULL,currency VARCHAR(16) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'active',deleted_at DATETIME(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS currencies (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(16) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL,rate DECIMAL(20,8) NOT NULL,decimals INT NOT NULL DEFAULT 2,symbol VARCHAR(16) NOT NULL DEFAULT '',status VARCHAR(16) NOT NULL DEFAULT 'active',created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS quota_ratios (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workplace_id INT UNSIGNED NULL,name VARCHAR(255) NOT NULL,percentage DECIMAL(7,4) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS module_settings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workplace_id INT UNSIGNED NULL,module VARCHAR(32) NOT NULL,`key` VARCHAR(255) NOT NULL,value JSON NOT NULL,updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS opening_debts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,account_id INT UNSIGNED NOT NULL,workplace_id INT UNSIGNED NULL,side VARCHAR(16) NOT NULL,debt_date DATE NOT NULL,amount DECIMAL(16,2) NOT NULL,currency VARCHAR(16) NOT NULL,note TEXT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS financial_entries (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workplace_id INT UNSIGNED NULL,account_id INT UNSIGNED NULL,cash_box_id INT UNSIGNED NULL,type VARCHAR(32) NOT NULL,entry_date DATE NOT NULL,category VARCHAR(255) NOT NULL,description TEXT NOT NULL,amount DECIMAL(16,2) NOT NULL,currency VARCHAR(16) NOT NULL,payment_method VARCHAR(32) NOT NULL,due_date DATE,status VARCHAR(16) NOT NULL DEFAULT 'posted',attachment_url TEXT,deleted_at DATETIME(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workplace_id INT UNSIGNED NULL,account_id INT UNSIGNED NOT NULL,cash_box_id INT UNSIGNED NULL,direction VARCHAR(16) NOT NULL,payment_date DATE NOT NULL,amount DECIMAL(16,2) NOT NULL,currency VARCHAR(16) NOT NULL,payment_method VARCHAR(32) NOT NULL,reference_type VARCHAR(64),reference_id INT UNSIGNED,note TEXT NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'posted',deleted_at DATETIME(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS business_documents (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,number VARCHAR(64) NOT NULL,kind VARCHAR(32) NOT NULL,account_id INT UNSIGNED NOT NULL,document_date DATE NOT NULL,valid_until DATE,total DECIMAL(16,2) NOT NULL DEFAULT 0,currency VARCHAR(16) NOT NULL,discount DECIMAL(16,2) NOT NULL DEFAULT 0,tax DECIMAL(16,2) NOT NULL DEFAULT 0,paid_amount DECIMAL(16,2) NOT NULL DEFAULT 0,status VARCHAR(16) NOT NULL DEFAULT 'draft',notes TEXT NOT NULL,deleted_at DATETIME(3),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS stock_transfers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,from_warehouse_id INT UNSIGNED NOT NULL,to_warehouse_id INT UNSIGNED NOT NULL,transfer_date DATE NOT NULL,note TEXT NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'draft',created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS stock_movements (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,warehouse_id INT UNSIGNED NOT NULL,item_id INT UNSIGNED NOT NULL,movement_date DATE NOT NULL,type VARCHAR(32) NOT NULL,quantity DECIMAL(14,2) NOT NULL,reference_type VARCHAR(64),reference_id INT UNSIGNED,note TEXT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;